package com.mirigangneung.course.dto; import com.mirigangneung.course.domain.*; import java.util.*;
public record CourseResponse(String courseId,String title,String duration,List<StopResponse> stops,int totalDistanceMeters,int totalTravelMinutes){public record StopResponse(int sequence,String placeId,String name,String thumbnailUrl,String arrivalTime,int stayMinutes,String crowdLevel,boolean isOnePick,String note,Double latitude,Double longitude){} public static CourseResponse from(Course c,List<CourseStop>s){return new CourseResponse(c.getId().toString(),c.getTitle(),c.getDurationType(),s.stream().map(x->new StopResponse(x.getSequence(),x.getPlace().getId().toString(),x.getPlace().getName(),x.getPlace().getThumbnailUrl(),x.getArrivalTime(),x.getStayMinutes(),x.getCrowdLevel(),x.isOnePick(),x.getNote(),x.getLatitudeSnapshot(),x.getLongitudeSnapshot())).toList(),0,0);}}
